sys_ws_operation.operation_script:
(function process(request, response) {
    try {
        var body = request.body.data; // Veriff sends JSON payloads
        var id = "";
        var status = "";
        var matchStatus = "";
		var response_body = "";
        if (body.verification) {
            id = body.verification.id;
            status = body.verification.status;
        } else if (body.matchStatus) {
            id = body.sessionId;
            matchStatus = body.matchStatus;
			response_body = JSON.stringify(body.hits || []);
        } else {
            id = body.id;
            status = body.action;
        }
        gs.info("Veriff webhook received: " + JSON.stringify(body));
        gs.info("id " + id);
        gs.info("action " + status);

        // Example: store in a log table
        var gr = new GlideRecord("x_vuram_financia_0_fcc_kyc_individual_details");
        gr.addQuery('session_id', id);
        gr.query();
        if (gr.next()) {
            if (matchStatus == 'possible_match') {
                gr.pep = 'possible_match_found';
                gr.adverse_news_screening = 'possible_match_found';
                gr.sanctions = 'possible_match_found';
				gr.response = response_body;
            } else if (matchStatus == 'no_match') {
                gr.pep = 'no';
                gr.adverse_news_screening = 'no';
                gr.sanctions = 'no';
            } else {
                gr.video_kyc_status = status;
            }
            gr.update();
        } else {
            var gr1 = new GlideRecord("x_vuram_financia_0_fcc_kyc_entity_details");
            gr1.addQuery('session_id', id);
            gr1.query();
            if (gr1.next()) {
                if (matchStatus == 'possible_match') {
                    gr1.pep = 'possible_match_found';
                    gr1.adverse_news_screening = 'possible_match_found';
                    gr1.sanctions = 'possible_match_found';
					gr1.response = response_body;
                } else if (matchStatus == 'no_match') {
                    gr1.pep = 'no';
                    gr1.adverse_news_screening = 'no';
                    gr1.sanctions = 'no';
                } else {
                    gr1.video_kyc_status = status;
                }
				gr1.update();
            }          
        }
        response.setStatus(200);
        response.setBody({
            received: true
        });
    } catch (e) {
        gs.error("Error in Veriff webhook: " + e.message);
        response.setStatus(500);
        response.setBody({
            error: e.message
        });
    }
})(request, response);
